-- ============================================================
-- FieldCheck · Migration 0019 — Seed do catálogo mestre v2 (Marco E)
-- GERADO por scripts/gen-seed-v2.mjs — não editar à mão.
-- 83 checklists / 643 itens / 6 kits-modelo. empresa_id = NULL.
-- Idempotente: UUID v5 determinístico + ON CONFLICT DO UPDATE. Aplicar após a 0018.
-- ============================================================
begin;

on conflict (id) do update set
  area = excluded.area, referencia = excluded.referencia, nome = excluded.nome, ativo = true,
  modulo = excluded.modulo, tipo = excluded.tipo, fase = excluded.fase,
  referencia_documento = excluded.referencia_documento, nrs_relacionadas = excluded.nrs_relacionadas,
  exige_projeto_ref = excluded.exige_projeto_ref;

on conflict (id) do update set
  ordem = excluded.ordem, texto = excluded.texto, criterio = excluded.criterio;

on conflict (id) do update set nome = excluded.nome, ativo = true;

delete from public.kit_checklists where kit_id in ('ca8939e5-5acd-525b-b651-aeda19b7560c', 'f8cadcbb-f702-557f-98d2-b0b9c97987e9', '4c6a17a5-ab88-52fd-8c15-a75df60bbbb5', '494035aa-6287-5aeb-9733-2d3b86b46a95', 'cf508437-a116-57d8-bc4a-1abef7e1054d', '6f0c9dd5-497f-5fdc-8c71-ff6c022cf671');
on conflict (kit_id, checklist_id) do nothing;

-- Sugestão de classificação (Bird) por item de checklist de segurança (tipo seguranca_nr).
update public.itens_checklist i set classificacao_st_sugerida = 'ato_inseguro'
  from public.checklists c
 where c.id = i.checklist_id and c.tipo = 'seguranca_nr' and i.classificacao_st_sugerida is null
   and (i.texto ilike '%epi%' or i.texto ilike '%uso %' or i.texto ilike '%utiliza%'
        or i.texto ilike '%procedimento%' or i.texto ilike '%apr%' or i.texto ilike '%permiss%'
        or i.texto ilike '%treina%' or i.texto ilike '%capacita%' or i.texto ilike '%comportament%'
        or i.texto ilike '%conduta%' or i.texto ilike '%integra%' or i.texto ilike '%habilita%');
update public.itens_checklist i set classificacao_st_sugerida = 'condicao_insegura'
  from public.checklists c
 where c.id = i.checklist_id and c.tipo = 'seguranca_nr' and i.classificacao_st_sugerida is null;

commit;
